<script setup lang="ts">
import { errorMessage } from '~/utils/inventory'
import InventoryBadge from '~/components/inventory/InventoryBadge.vue'
const api = useInventoryApi()
const { data, error, refresh } = await useAsyncData('inventory-overview', async () => {
  const [products, orders, purchases, lowStock, transfers] = await Promise.all([api.list('products', { per_page: 1 }), api.list('orders', { per_page: 5 }), api.list('purchase-orders', { per_page: 5 }), api.list('products', { low_stock: true, per_page: 5 }), api.list('stock-transfers', { per_page: 1 })])
  return { products, orders, purchases, lowStock, transfers }
})
useHead({ title: 'Overview · Brickventory' })
</script>
<template><div><header class="page-header"><div><p class="eyebrow">Workspace overview</p><h1>Inventory, in focus.</h1><p>Keep track of your stock, sales and purchasing.</p></div><div class="actions"><NuxtLink class="button" to="/stock-adjustments/new">Adjust stock</NuxtLink><NuxtLink class="button primary" to="/orders/new">+ New order</NuxtLink></div></header><p v-if="error" class="error" role="alert">{{ errorMessage(error) }} <button @click="refresh()">Retry</button></p><template v-if="data"><section class="stat-grid" aria-label="Inventory summary"><article v-for="metric in [{ title: 'Products', count: data.products.meta.total, path: '/products' }, { title: 'Orders', count: data.orders.meta.total, path: '/orders' }, { title: 'Purchase orders', count: data.purchases.meta.total, path: '/purchase-orders' }, { title: 'Low-stock products', count: data.lowStock.meta.total, path: '/products?low_stock=true' }]" :key="metric.title" class="panel stat-card"><small>{{ metric.title }}</small><strong>{{ metric.count.toLocaleString() }}</strong><NuxtLink :to="metric.path">View records →</NuxtLink></article></section><div class="dashboard-grid"><section class="panel"><header class="section-header"><h2>Recent orders</h2><NuxtLink to="/orders">All orders →</NuxtLink></header><div v-for="order in data.orders.data" :key="order.id" class="history-row"><NuxtLink :to="`/orders/${order.id}`">{{ order.number }}</NuxtLink><InventoryBadge :value="order.status"/><strong>{{ order.total }} {{ order.details?.currency || '' }}</strong></div><p v-if="!data.orders.data.length" class="muted">Your orders will appear here.</p></section><section class="panel"><header class="section-header"><h2>Restock soon</h2><NuxtLink to="/purchase-orders/new">+ Purchase order</NuxtLink></header><div v-for="product in data.lowStock.data" :key="product.id" class="history-row"><NuxtLink :to="`/products/${product.id}`">{{ product.name }}</NuxtLink><span>{{ product.stock }} on hand · minimum {{ product.min_stock }}</span></div><p v-if="!data.lowStock.data.length" class="muted">All products are above their minimum stock level.</p></section></div></template></div></template>
